using System.Linq;

class SyncJob
{
    void Run(BlogContext context)
    {
        // Breaking change 4: Sync I/O removed in EF Core 9 Cosmos provider.
        // Must use async equivalents.
        async System.Threading.Tasks.Task RunAsync()
